HP = f'{{{HWP_NS}}}'
ET.register_namespace('hp', HWP_NS)


def localname(tag: str) -> str:
    if tag.startswith('{'):
        return tag.split('}', 1)[1]
    return tag


def replace_in_paragraph(p_elem: ET.Element):
