def remove_layout_cache_everywhere(root: ET.Element) -> int:
    # Remove any element whose localname is linesegarray or lineseg, anywhere in tree.
    # Do this via parent-child scanning since ElementTree lacks getparent().
    removed = 0

    def recurse(parent: ET.Element):
        nonlocal removed
        # iterate over a snapshot of children since we may remove
        for child in list(parent):
            ln = str(localname(child.tag)).lower()
            if ln in ('linesegarray', 'lineseg'):
                parent.remove(child)
                removed += 1
                continue
            recurse(child)

